overall_score: 8.5
overall_score_pre_cap: 9.5
verdict: pass
cap_applied: "inflation guard - 4 WARN-tier auto_surfaced entries (>=2) caps overall at 8.5"
verdict_derivation: >-
  Ordered cascade (LEARN_APP_BANDS): rule 1 no scored dimension <=3 and no 5b BLOCKER;
  rule 2 no scored dimension <7 and overall 8.5 >= 7.5; rule 3 fires -> pass.


dimensions:
  module_count_match:       { score: 9.0,  weight: 0.07 }
  module_order_match:       { score: 10.0, weight: 0.06 }
  assessment_score_wiring:  { score: 10.0, weight: 0.12 }
  content_topic_coverage:   { score: 10.0, weight: 0.12 }
  archetype_coherence:      { score: 10.0, weight: 0.08 }
