  language_conformance:     { score: 10.0, weight: 0.08 }


hard_gates:
  naming_convention: { result: pass, evidence: "get_app name = 'Spark Facilitator Learn app'" }
  form_navigation:   { result: pass, evidence: "all 8 forms postSubmit: previous (read via get_form on each)" }
  single_gating_assessment: { result: pass, evidence: "only Final assessment carries connect.assessment (final_quiz); Starting quiz carries learn_module m0_pretest only" }
  deferred_not_graded: "grid-menu-display and assessment-display-lifecycle are applied post-build by app-hq-settings; not representable in the Nova blueprint, not graded here per rubric 5b"


per_item:
  - ref: module_count_match
    score: 9.0
    verdict: pass
    note: "PDD 4.1 = 6 modules; build = 8 (6 PDD modules + 'Before you start' pre-test + 'Final assessment' cert module). Assessment-only cert module = bonus-module rule; the pre-test module is an addition -> 1-point deduction (defensible, see INFO)."
  - ref: module_order_match
    score: 10.0
    verdict: pass
    note: "Lessons 1-6 in exact PDD order (role, register, record, counts, steps+savings, payment), bracketed by pre-test and final."
  - ref: assessment_score_wiring
    score: 10.0
    verdict: pass
    note: "connect.assessment final_quiz, user_score = #form/your_result/user_score = sum(q1..q12)*100 div 12; 12 items, pass at 80 (10/12) matches PDD 4.2 / 14 learn_passing_score 80, assessment_items 12."
  - ref: content_topic_coverage
    score: 10.0
    verdict: pass
    note: "Every PDD 4.1 'must be able to do' topic is present: pay unit/FCAP unchanged/reviewers (L1); register once, enrol once, whole-community household count, consent-to-calls No respected (L2); screen-by-screen record, wide live photo during meeting, not-held branch with reasons + reschedule (L3); households/attendance/speakers, people-not-times (L4); step read from record, forward-only, savings from Step 5 (L5); payable unit, 3-per-step, 1-per-day, recorded-unpaid (L6). No placeholder answer keys. FIYP video absent is PDD-sanctioned (module written to stand alone)."
  - ref: archetype_coherence
    score: 10.0
    verdict: pass
    note: "longitudinal-visits framing throughout: the community as followed entity, step pointer state, per-step meeting counter/cap, community leaving the list at Step 7, supervisor-only correction of a wrongly advanced step. No facilitation-craft drift (PDD scope discipline respected)."
  - ref: assessment_gating
    score: 9.0
    verdict: pass
    note: "(a) distinct pre-test (6, non-gating) + post-test (12, gating) banks; (b) 12 items = 2 per taught module, all 7 PDD 8.3 counter-intuitive rules in the GATING bank by name (q10,q5,q11,q6,q8,q4,q12); (c) percentage wired to connect.assessment at 80; (d) conditional pass (>=80) and fail (<80) labels, no unconditional 'Well done'; (e) per-module revisit labels on fail keyed to item scores. -1: fixed bank with unlimited retakes (PDD-acknowledged) and a longest-option tell on q1/q5/q6 soften the gate."
  - ref: instructional_depth
    score: 9.0
    verdict: pass
    note: "Every lesson carries sectioned teaching prose, a named worked example drawn from the real Meeting Record (Grace / Kalumbu), explicit Right/Wrong pairs (L4, L5), Good/Not-good photo pair (L3), a practice check with conditional feedback, and a Remember recap. Mid-tier cap does not apply (worked examples + do/don't present; 2 scored items per module). -1: L1 'People review every record' overstates the PDD 7.2 design (risk-stratified >=20% sample + >=10% calls)."
  - ref: assessment_rule_coverage
    score: 9.5
    verdict: pass
    note: "Weighted coverage (12x2 + 8)/(12x2 + 9) = 32/33 = 0.97 across both banks; 0 items excluded; 0 items mapping to nothing. One uncovered operation (facilitator registration once) -> repairs[]."
  - ref: language_conformance
    score: 10.0
    verdict: pass
    note: "Anchor (a): English is sourceLanguage and default, 320/320 ready; nya and tum each 320 units, 0 missing, 0 out-of-date, sampled units origin: ai with real target text (e.g. 'Mayeso omaliza', Tumbuka lesson prose) - not copied English. needs-review is not a deduction."


rule_coverage:
  enumeration_source: "PDD 8.3 (7 rules) + counter-intuitive rules taught in lesson text L1-L6 + PDD 4.2 named high-consequence operations (7) + L2 facilitator registration + L4 count-on-the-day (PDD 4.2 states 9 operations)"
  counter_intuitive_rules:
    - {id: CI-1,  rule: "a committee meeting is recorded and NOT paid", taught_in: m6_payment, covered_by: post.q10}
    - {id: CI-2,  rule: "people who spoke never exceed attendees; count people not times", taught_in: m4_counts, covered_by: post.q5}
    - {id: CI-3,  rule: "max 3 paid meetings per step; 4th recorded in full, unpaid", taught_in: m6_payment, covered_by: post.q11}
    - {id: CI-4,  rule: "step is read from the record, moves forward only on step_completed = yes; CBF cannot pick it", taught_in: m5_steps, covered_by: post.q6}
    - {id: CI-5,  rule: "no savings questions before Step 5 is correct, not a bug", taught_in: m5_steps, covered_by: post.q8}
    - {id: CI-6,  rule: "a planned meeting that did not happen is still recorded (reason + new date) and not paid", taught_in: "m3_record, m6_payment", covered_by: post.q4}
    - {id: CI-7,  rule: "paid per verified meeting (not hour/attendee/household), at most 1 per day; same-day continuation = same record", taught_in: m6_payment, covered_by: post.q12}
    - {id: CI-8,  rule: "a wrongly-advanced step cannot be undone in the app; supervisor corrects on HQ", taught_in: m5_steps, covered_by: post.q7}
    - {id: CI-9,  rule: "enrolment household count = whole community, not those at the enrolment meeting", taught_in: m2_register, covered_by: post.q2}
    - {id: CI-10, rule: "progress speed does not change pay (monitored, not priced)", taught_in: m6_payment, covered_by: pre.q6}
    - {id: CI-11, rule: "a contact's No to calls keeps the community in the pilot", taught_in: m2_register, covered_by: pre.q2}
    - {id: CI-12, rule: "a community that completed Step 7 leaves the list - correct, not lost", taught_in: m3_record, covered_by: pre.q3}
  operations:
    - {id: OP-1, operation: "enrol each community once (check the list first)", covered_by: post.q1}
    - {id: OP-2, operation: "household count at enrolment (feeds households-represented constraint)", covered_by: post.q2}
    - {id: OP-3, operation: "step_completed answered honestly / corrected via supervisor", covered_by: "pre.q5, post.q7"}
    - {id: OP-4, operation: "not-held branch (reason codes + reschedule date)", covered_by: post.q4}
    - {id: OP-5, operation: "attendance vs participation counts", covered_by: post.q5}
    - {id: OP-6, operation: "meeting photo: one wide live photo during the meeting", covered_by: post.q3}
    - {id: OP-7, operation: "savings amounts only when currently_saving = yes", covered_by: post.q9}
    - {id: OP-8, operation: "count attendance on the day, never copy last week (repeat_counts_flag)", covered_by: pre.q4}
    - {id: OP-9, operation: "register as facilitator once; stop on 'already registered'", covered_by: null}
  counter_intuitive_covered: 12
  operations: 9
  operations_covered: 8
  weighted_ratio: 0.97
  items_excluded: 0
  items_mapping_to_nothing: []
  derivable_pairs: []


items:
  - {id: post.q1,  rule: OP-1,  rejectable_distractors: 1, qualifies: true, surviving: "a 'Enrol it again to be safe' - a cautious worker plausibly re-enrols rather than risk a missing record"}
  - {id: post.q2,  rule: CI-9,  rejectable_distractors: 2, qualifies: true, surviving: "b '60, at the enrolment meeting' - the number actually in front of the worker"}
  - {id: post.q3,  rule: OP-6,  rejectable_distractors: 0, qualifies: true, surviving: "b 'wide photo after the meeting ends' - the natural group-photo habit"}
  - {id: post.q4,  rule: CI-6,  rejectable_distractors: 1, qualifies: true, surviving: "a 'nothing to record' and c 'paid because you went' - both common-sense readings"}
  - {id: post.q5,  rule: CI-2,  rejectable_distractors: 1, qualifies: true, surviving: "b '15, number of times' - counting contributions is intuitive"}
  - {id: post.q6,  rule: CI-4,  rejectable_distractors: 1, qualifies: true, surviving: "a 'you pick the step' - exactly how Spark's own form works today"}
  - {id: post.q7,  rule: CI-8,  rejectable_distractors: 1, qualifies: true, surviving: "a 'answer No next time to move it back' - reasonable self-repair assumption"}
  - {id: post.q8,  rule: CI-5,  rejectable_distractors: 1, qualifies: true, surviving: "a 'app has a problem, report it' - the default reaction to a missing question"}
  - {id: post.q9,  rule: OP-7,  rejectable_distractors: 1, qualifies: true, surviving: "a 'Yes, and 0 for each amount' - 0 feels like the honest amount"}
  - {id: post.q10, rule: CI-1,  rejectable_distractors: 1, qualifies: true, surviving: "b 'both meetings' - both were real work"}
  - {id: post.q11, rule: CI-3,  rejectable_distractors: 1, qualifies: true, surviving: "a 'paid like every held community meeting' - the default expectation"}
  - {id: post.q12, rule: CI-7,  rejectable_distractors: 1, qualifies: true, surviving: "a 'as two meetings' - two sessions of work"}
  - {id: pre.q1,   rule: "review model (OP context)", rejectable_distractors: 1, qualifies: true, surviving: "a 'app checks location and photo then pays automatically'"}
  - {id: pre.q2,   rule: CI-11, rejectable_distractors: 1, qualifies: true, surviving: "a 'find another contact who agrees'"}
  - {id: pre.q3,   rule: CI-12, rejectable_distractors: 1, qualifies: true, surviving: "b 'record was lost, enrol again'"}
  - {id: pre.q4,   rule: OP-8,  rejectable_distractors: 1, qualifies: true, surviving: "a '25, same as last week'"}
  - {id: pre.q5,   rule: OP-3,  rejectable_distractors: 1, qualifies: true, surviving: "b 'Yes, because the community worked on Step 3 today'"}
  - {id: pre.q6,   rule: CI-10, rejectable_distractors: 1, qualifies: true, surviving: "c 'paid only when the community completes a step'"}


repairs:
  - uncovered_rule: "register as a facilitator once; if the form says 'This facilitator is already registered', stop"
    kind: no-item
    taught_in: m2_register
    failure_prevented: corrupted-data (duplicate cbf case)
    suggested_target: pre.q1
    note: >-
      Taught in Lesson 2 and exercised only by an unscored practice check. Lowest-consequence
      gap in the bank (registration is unpaid and Spark's own duplicate warning fires), so a
      pre-test re-key is sufficient; do NOT displace a gating item for it.


auto_surfaced:
  - severity: WARN
    message: "repairs[]: facilitator-registration-once (L2) has no scored item in either bank; suggested re-key of pre-test q1."
  - severity: WARN
    message: "Gate does not certify two taught rules (build memo names the trade): the reschedule-date rule (Lesson 3 practice only) and count-on-the-day (starting quiz q4 only, non-gating). A worker can pass without being examined on either."
  - severity: WARN
    message: "Lesson 1 'People review every record' overstates PDD 7.2 (risk-stratified >=20% Layer B sample, >=10% Layer C calls). Suggest 'People check records' / 'any record may be checked'."
  - severity: WARN
    message: "Option-craft tell (memo-named): the correct option is the longest on post q1, q5, q6 (and starting-quiz q1). Hygiene, not a coverage defect; equalise option lengths."
  - severity: INFO
    message: "Bonus modules: 'Before you start' (non-gating pre-test, learn_module only) and 'Final assessment' (assessment-only cert module) - defensible structural additions."
  - severity: INFO
    message: "Retakes unlimited against a fixed 12-item bank (PDD 4.2 states this and carries it as an open question / capability request)."
  - severity: INFO
    message: "Language coverage: eng 320 ready (source+default); nya 320 needs-review / 0 ready / 0 out-of-date / 0 missing; tum identical. Sampled units origin: ai with real target text. ACE-authored, awaiting the same human review as the English; Tumbuka flagged lower-confidence in the memo. 8 Connect learn-module name/description units stay English by Nova design."
  - severity: INFO
    message: "Taught-vs-collectable not re-run via lib; spot-check: Lesson 3 photo/not-held/step-completed teaching matches PDD 5.4 screens 3a, 6, 11 relevance (photo only on held meeting, step_completed only on community meeting)."
  - severity: INFO
    message: "Grid menu display and media not graded here - applied later by app-hq-settings / app-media-coverage (rubric 5b deferral)."
  - severity: INFO
    message: "No known-issues.md in ACE/spark-facilitator/eval-calibration/ (only app-ux-eval-runs.md); no catalogue to score detection against."


gate:
  threshold: 7.5
  disposition: approve
